#!/usr/bin/env python3
import numpy as np
import pandas as pd
from netCDF4 import Dataset
from datetime import datetime, timedelta
import subprocess
from scipy.optimize import minimize
import warnings
warnings.filterwarnings('ignore')

# Load observation data
obs_df = pd.read_csv('/root/field_temp_oxy.csv')
obs_df['datetime'] = pd.to_datetime(obs_df['datetime'])

def calculate_rmse_from_output():
    """Calculate RMSE from netCDF output"""
    try:
        nc = Dataset('/root/output/output.nc', 'r')
    except:
        return float('inf')

    try:
        temp = nc.variables['temp'][:]
        z = nc.variables['z'][:]

        temp = np.ma.filled(temp, np.nan)
        z = np.ma.filled(z, np.nan)

        time_vals = nc.variables['time'][:]
        time_var = nc.variables['time']

        time_units = time_var.units
        ref_date_str = time_units.split("since ")[1]
        ref_date = datetime.strptime(ref_date_str.strip(), "%Y-%m-%d %H:%M:%S")

        if "hours" in time_units:
            time_coord = [ref_date + timedelta(hours=float(t)) for t in time_vals]
        elif "days" in time_units:
            time_coord = [ref_date + timedelta(days=float(t)) for t in time_vals]
        else:
            time_coord = [ref_date + timedelta(seconds=float(t)) for t in time_vals]

        time_coord = pd.to_datetime(time_coord)

        temp_1d = temp[:, :, 0, 0]
        z_1d = z[:, :, 0, 0]

        rmse_list = []

        for obs_idx, obs_row in obs_df.iterrows():
            obs_time = obs_row['datetime']
            obs_depth = obs_row['depth']
            obs_temp = obs_row['temp']

            if pd.isna(obs_temp):
                continue

            time_diff = np.abs((time_coord - obs_time).total_seconds())
            closest_idx = np.argmin(time_diff)

            if time_diff[closest_idx] < 3600:
                sim_at_time = temp_1d[closest_idx, :]
                z_at_time = z_1d[closest_idx, :]

                valid_mask = ~np.isnan(z_at_time)
                if np.any(valid_mask):
                    valid_z = z_at_time[valid_mask]
                    valid_idx = np.where(valid_mask)[0]

                    depth_diff = np.abs(valid_z - obs_depth)
                    closest_valid_idx = np.argmin(depth_diff)
                    closest_depth_idx = valid_idx[closest_valid_idx]

                    if depth_diff[closest_valid_idx] < 1.0:
                        sim_temp = sim_at_time[closest_depth_idx]

                        if not np.isnan(sim_temp):
                            error = obs_temp - float(sim_temp)
                            rmse_list.append(error ** 2)

        if rmse_list:
            rmse = np.sqrt(np.mean(rmse_list))
            nc.close()
            return rmse
        else:
            nc.close()
            return float('inf')
    except Exception as e:
        nc.close()
        return float('inf')


def run_glm_with_params(ws, conv, shear, turb, sw, lw):
    """Run GLM with specified parameters"""
    with open('/root/glm3.nml', 'r') as f:
        lines = f.readlines()

    new_lines = []
    for line in lines:
        if 'coef_wind_stir = ' in line:
            new_lines.append(f"   coef_wind_stir = {ws}\n")
        elif 'coef_mix_conv = ' in line:
            new_lines.append(f"   coef_mix_conv = {conv}\n")
        elif 'coef_mix_shear = ' in line:
            new_lines.append(f"   coef_mix_shear = {shear}\n")
        elif 'coef_mix_turb = ' in line:
            new_lines.append(f"   coef_mix_turb = {turb}\n")
        elif 'sw_factor = ' in line and 'coef' not in line:
            new_lines.append(f"   sw_factor = {sw}\n")
        elif 'lw_factor = ' in line:
            new_lines.append(f"   lw_factor = {lw}\n")
        else:
            new_lines.append(line)

    with open('/root/glm3.nml', 'w') as f:
        f.writelines(new_lines)

    result = subprocess.run(['glm', '--nml', 'glm3.nml'],
                          cwd='/root',
                          capture_output=True,
                          timeout=120)

    return result.returncode == 0


def objective(x):
    """Objective function to minimize"""
    ws, conv, shear, turb, sw, lw = x

    # Bounds check
    if ws < 0.1 or ws > 2.0 or conv < 0.1 or conv > 2.0:
        return float('inf')
    if shear < 0.1 or shear > 2.0 or turb < 0.1 or turb > 2.0:
        return float('inf')
    if sw < 0.2 or sw > 1.5 or lw < 0.4 or lw > 1.5:
        return float('inf')

    if run_glm_with_params(ws, conv, shear, turb, sw, lw):
        rmse = calculate_rmse_from_output()
        return rmse
    else:
        return float('inf')


# Initial guess (current best)
x0 = np.array([1.0, 1.0, 1.0, 1.0, 0.7, 0.8])

print("Running scipy optimization...")
print(f"Initial RMSE: {objective(x0):.4f}°C")

# Use Nelder-Mead optimization
result = minimize(objective, x0, method='Nelder-Mead',
                 options={'maxiter': 20, 'xatol': 0.05, 'fatol': 0.1, 'adaptive': True})

print(f"\nOptimization result:")
print(f"Final RMSE: {result.fun:.4f}°C")
print(f"Parameters: {result.x}")
print(f"Iterations: {result.nit}")

ws, conv, shear, turb, sw, lw = result.x

print(f"\nBest parameters found:")
print(f"  wind_stir: {ws:.4f}")
print(f"  conv: {conv:.4f}")
print(f"  shear: {shear:.4f}")
print(f"  turb: {turb:.4f}")
print(f"  sw_factor: {sw:.4f}")
print(f"  lw_factor: {lw:.4f}")

if result.fun < 2.0:
    print(f"\n✓ SUCCESS: RMSE {result.fun:.4f}°C < 2.0°C!")
else:
    print(f"\nRMSE {result.fun:.4f}°C (target: < 2.0°C)")

